S = "Hakeem Force Academy"
QS = [
(S, "In which year was the United Nations Organization (UNO) formed?", ["1919", "1945", "1948", "1955"], 1, "The United Nations officially came into existence on 24 October 1945 after the UN Charter was ratified.", "Its predecessor, the League of Nations, was formed in 1919.", 1),
(S, "In which year was the World Trade Organization (WTO) established?", ["1985", "1991", "1995", "2001"], 2, "The WTO came into being on 1 January 1995, replacing the GATT arrangement.", "The WTO is headquartered in Geneva, Switzerland.", 1),
(S, "In which province of Pakistan are the Chagai Hills located?", ["Balochistan", "Sindh", "Khyber Pakhtunkhwa", "Punjab"], 0, "The Chagai Hills lie in Chagai district in the northwest of Balochistan, near the Afghan and Iranian borders.", "Pakistan conducted its nuclear tests of May 1998 in the Chagai Hills.", 3),
(S, "At which place did Allama Iqbal deliver his famous Presidential Address of 1930 in which he presented the idea of a separate Muslim state?", ["Lahore", "Delhi", "Allahabad", "Aligarh"], 2, "Iqbal delivered the Presidential Address at the annual session of the All-India Muslim League held at Allahabad in December 1930.", "The Lahore Resolution was passed ten years later, in March 1940.", 1),
(S, "Which country is regarded as the place of origin of the game of chess?", ["China", "Persia", "India", "Greece"], 2, "Chess developed from the ancient Indian game Chaturanga in about the 6th century AD, and then spread to Persia and the world.", "The word checkmate comes from the Persian shah mat.", 1),
(S, "In which region does the Yellow River (Huang He) of China originate?", ["Bayan Har Mountains, Qinghai", "Gobi Desert", "Yunnan Plateau", "Mount Everest region"], 0, "The Yellow River rises in the Bayan Har Mountains in Qinghai province on the Tibetan Plateau and flows east to the Bohai Sea.", "It is the second longest river in China after the Yangtze.", 1),
(S, "In which country is Angel Falls, the world's highest uninterrupted waterfall, located?", ["Brazil", "Colombia", "Venezuela", "Zambia"], 2, "Angel Falls (Salto Angel) is in Canaima National Park in Bolivar state, Venezuela.", "It is about 979 metres high.", 1),
(S, "In which province of Pakistan is Ghotki located?", ["Punjab", "Balochistan", "Sindh", "Khyber Pakhtunkhwa"], 2, "Ghotki is a city and district in northern Sindh, on the border with Punjab.", "Ghotki lies on the Indus highway between Sukkur and Rahim Yar Khan.", 1),
(S, "Where is Jabal-e-Noor (the mountain containing the Cave of Hira) located?", ["Madinah", "Taif", "Makkah", "Jeddah"], 2, "Jabal al-Noor is a mountain near Makkah in Saudi Arabia and holds the Cave of Hira where the first revelation came to the Prophet (PBUH).", "The first revelation, the opening verses of Surah Al-Alaq, was received in this cave.", 2),
(S, "In which district of Khyber Pakhtunkhwa is Khanpur Dam located?", ["Haripur", "Abbottabad", "Mansehra", "Swat"], 0, "Khanpur Dam is on the Haro River near Khanpur in Haripur district, Khyber Pakhtunkhwa.", "It supplies water to Islamabad and Rawalpindi.", 1),
(S, "Where is Lake Superior located?", ["Africa", "South America", "North America", "Europe"], 2, "Lake Superior is the northernmost of the Great Lakes and lies between the USA and Canada in North America.", "It is the largest freshwater lake in the world by surface area.", 1),
(S, "Where is the MAO College (founded by Sir Syed Ahmad Khan) located?", ["Lahore", "Aligarh", "Delhi", "Lucknow"], 1, "The Muhammadan Anglo-Oriental College was founded in 1875 at Aligarh by Sir Syed Ahmad Khan.", "It later became Aligarh Muslim University in 1920.", 1),
(S, "In which city is the Margalla Hills National Park located?", ["Lahore", "Peshawar", "Islamabad", "Murree"], 2, "The Margalla Hills form the northern backdrop of Islamabad, the capital of Pakistan.", "Faisal Mosque lies at the foot of the Margalla Hills.", 1),
(S, "In which district of Sindh are the ruins of Mohenjo-daro located?", ["Larkana", "Hyderabad", "Sukkur", "Thatta"], 0, "Mohenjo-daro lies near Dokri in Larkana district, Sindh, on the right bank of the Indus.", "It was declared a UNESCO World Heritage Site in 1980.", 2),
(S, "Which Indian Ocean water body is the Bay of Bengal part of?", ["Indian Ocean, northeast part", "Pacific Ocean", "Arabian Sea", "Atlantic Ocean"], 0, "The Bay of Bengal is the northeastern part of the Indian Ocean, bordered by India, Bangladesh, Myanmar and Sri Lanka.", "It is the largest bay in the world.", 1),
(S, "Between which two countries does the Bay of Bothnia lie?", ["Norway and Denmark", "Sweden and Finland", "Germany and Poland", "Latvia and Estonia"], 1, "The Gulf or Bay of Bothnia is the northern arm of the Baltic Sea between Sweden and Finland.", "It is the northernmost part of the Baltic Sea.", 1),
(S, "Between which countries does the Gulf (Bay) of Riga lie?", ["Latvia and Estonia", "Sweden and Finland", "Poland and Lithuania", "Denmark and Germany"], 0, "The Gulf of Riga is an inlet of the Baltic Sea bordered by Latvia and Estonia.", "Its main port is Riga, the capital of Latvia.", 1),
(S, "In which country is Shark Bay, a UNESCO World Heritage Site, located?", ["South Africa", "Australia", "USA", "New Zealand"], 1, "Shark Bay is on the coast of Western Australia.", "It was listed as a World Heritage Site in 1991.", 1),
(S, "In which district of Pakistan is the Chashma nuclear power plant located?", ["Mianwali", "Bahawalpur", "Karachi", "Attock"], 0, "The Chashma Nuclear Power Complex stands near Chashma barrage on the Indus in Mianwali district, Punjab.", "Chashma Nuclear Power Plant Unit 1 was built with Chinese help.", 1),
(S, "In which region was the ancient Gandhara civilization centred?", ["Peshawar valley and Taxila region", "Lower Sindh", "Southern Balochistan", "Cholistan"], 0, "Gandhara flourished in the Peshawar valley and Potohar region of northwest Pakistan, with Taxila and Peshawar as major centres.", "Gandhara art is famous for Greco-Buddhist sculpture.", 1),
(S, "Where is the headquarters of SAARC located?", ["Dhaka", "Colombo", "Kathmandu", "New Delhi"], 2, "The SAARC Secretariat was established in Kathmandu, Nepal in 1987.", "SAARC was founded in 1985 in Dhaka.", 1),
(S, "Where is the headquarters of the United Nations located?", ["Geneva", "New York", "Washington DC", "Paris"], 1, "The UN headquarters is on the east side of Manhattan in New York City, USA.", "The UN also has major offices at Geneva, Vienna and Nairobi.", 1),
(S, "Where is the headquarters of the World Bank located?", ["New York", "Geneva", "London", "Washington DC"], 3, "The World Bank is headquartered in Washington DC, USA, not New York as some candidates think.", "The International Monetary Fund (IMF) is also headquartered in Washington DC.", 1),
(S, "Where is the headquarters of OPEC located?", ["Riyadh", "Vienna", "Geneva", "Dubai"], 1, "OPEC moved from Geneva to Vienna, Austria in 1965 and has been headquartered there since.", "OPEC was founded in Baghdad in 1960.", 1),
(S, "In which region of Pakistan does the River Soan flow?", ["Potohar Plateau", "Cholistan Desert", "Makran Coast", "Thal Desert"], 0, "The Soan rises in the Murree hills and flows through the Potohar Plateau near Rawalpindi and Islamabad before joining the Indus.", "The Soan valley is known for Stone Age sites.", 2),
(S, "In which city or area is Simly Dam located?", ["Islamabad", "Murree", "Lahore", "Abbottabad"], 0, "Simly Dam is on the Soan River in the Islamabad Capital Territory, about 30 km from the city.", "It is a major source of drinking water for Islamabad.", 1),
]
